static gboolean challenge_browser_message_codec_write_value(FlStandardMessageCodec* codec, GByteArray* buffer, FlValue* value, GError** error) {
  if (fl_value_get_type(value) == FL_VALUE_TYPE_CUSTOM) {
    switch (fl_value_get_custom_type(value)) {
      case challenge_browser_page_event_kind_type_id:
        return challenge_browser_message_codec_write_challenge_browser_page_event_kind(codec, buffer, reinterpret_cast<FlValue*>(const_cast<gpointer>(fl_value_get_custom_value(value))), error);
      case challenge_browser_focus_direction_type_id:
        return challenge_browser_message_codec_write_challenge_browser_focus_direction(codec, buffer, reinterpret_cast<FlValue*>(const_cast<gpointer>(fl_value_get_custom_value(value))), error);
      case challenge_browser_dialog_kind_type_id:
        return challenge_browser_message_codec_write_challenge_browser_dialog_kind(codec, buffer, reinterpret_cast<FlValue*>(const_cast<gpointer>(fl_value_get_custom_value(value))), error);
      case challenge_browser_page_event_type_id:
        return challenge_browser_message_codec_write_challenge_browser_page_event(codec, buffer, CHALLENGE_BROWSER_PAGE_EVENT(fl_value_get_custom_value_object(value)), error);
      case challenge_browser_page_cookie_type_id:
        return challenge_browser_message_codec_write_challenge_browser_page_cookie(codec, buffer, CHALLENGE_BROWSER_PAGE_COOKIE(fl_value_get_custom_value_object(value)), error);
      case challenge_browser_page_capabilities_type_id:
        return challenge_browser_message_codec_write_challenge_browser_page_capabilities(codec, buffer, CHALLENGE_BROWSER_PAGE_CAPABILITIES(fl_value_get_custom_value_object(value)), error);
      case challenge_browser_page_frame_type_id:
        return challenge_browser_message_codec_write_challenge_browser_page_frame(codec, buffer, CHALLENGE_BROWSER_PAGE_FRAME(fl_value_get_custom_value_object(value)), error);
    }
  }

  return FL_STANDARD_MESSAGE_CODEC_CLASS(challenge_browser_message_codec_parent_class)->write_value(codec, buffer, value, error);
}

